mapper.select:
SELECT user_id, login_type, identifier, credential
FROM blog_user_auth
WHERE identifier = #{identifier}
  AND login_type = #{loginType}
  AND deleted_at = 0

mapper.update:
UPDATE blog_user_auth
SET credential  = #{credential},
    update_time = NOW()
WHERE identifier = #{identifier}
  AND login_type = #{loginType}
  AND deleted_at = 0

UPDATE blog_user_auth
SET identifier  = #{newIdentifier},
    update_time = NOW()
WHERE user_id = #{userId}
  AND login_type = #{loginType}
  AND deleted_at = 0

mapper.select:
SELECT COUNT(*)
FROM blog_user_auth
WHERE user_id = #{userId}
  AND login_type = #{loginType}
  AND deleted_at = 0

mapper.update:
UPDATE blog_user_auth
SET deleted_at  = UNIX_TIMESTAMP(NOW()) * 1000,
    update_time = NOW()
WHERE user_id = #{userId}
  AND login_type = #{loginType}
  AND deleted_at = 0
